if(!clean(m.source_hash))findings.push({code:'SOURCE_HASH_REQUIRED',severity:'error'});else if(!/^sha256:[a-f0-9]{64}$/i.test(clean(m.source_hash)))findings.push({code:'SOURCE_HASH_INVALID',severity:'error'});
