const allowed=new Set(["DATES", "INCLUDE", "GRUPTREE", "WELSPECS", "WELLTRACK", "COMPDATMD", "WCONHIST", "WCONPROD", "GCONPROD", "BRANPROP", "NODEPROP", "FRACTURE_SPECS", "FRACTURE_STAGE", "WECON", "WTEST"]);
const keywordFamilies=[...new Set((text.match(/\b[A-Z][A-Z0-9_]+\b/g)||[]).filter(k=>allowed.has(k)))];
